use serde_json::Value;use sha2::{Digest,Sha256};use std::{fs,path::{Path,PathBuf}};
const D:&str="/home/ubuntu/src/zk-tools/zopro/docs/benchmarks/2026-10-31-g1-mixed9-176";
fn walk(p:&Path,v:&mut Vec<PathBuf>){for e in fs::read_dir(p).unwrap(){let e=e.unwrap();if e.file_type().unwrap().is_dir(){walk(&e.path(),v)}else{v.push(e.path())}}}
fn main(){let p=format!("{D}/README.md");let mut s=fs::read_to_string(&p).unwrap();for(a,b)in[("CPU2","CPU 2"),("CPUs0","CPUs 0"),("512KiB","512 KiB"),("factor1.03","factor 1.03"),("most1.05","most 1.05"),("ranks4–12","ranks 4–12"),("checks:24 gain,3 calibration,3 RSS","checks: 24 gain, 3 calibration, 3 RSS"),("from40,000 to39,040bytes at batch200","from 40,000 to 39,040 bytes at batch 200"),("and70,400 to68,800bytes at352","and 70,400 to 68,800 bytes at 352"),("All127","All 127"),("across0/1/7/8/9/10/17/18/23/199/200/352/511points","across 0/1/7/8/9/10/17/18/23/199/200/352/511 points"),("All540","All 540"),("have100%","have 100%"),("validates33,856","validates 33,856"),("exceeds1,000samples","exceeds 1,000 samples"),("than0.05%","than 0.05%"),("roughly57–60%","roughly 57–60%"),("and33%","and 33%"),("All588","All 588"),("has606","has 606"),("root-owned0600files","root-owned files with mode 0600"),("all588","all 588"),("accepted176-source","accepted 176-source"),("at27,851","at 27,851"),("remains161.883899ms/1876.96MiB","remains 161.883899 ms / 1876.96 MiB"),("The original CPU10× objective remains unmet for0/8 shapes.","The original CPU 10× objective remains unmet: 0/8 shapes meet the target."),("physical16","physical-16"),("fixed9-point","fixed 9-point")]{s=s.replace(a,b);}fs::write(&p,&s).unwrap();let m:Value=serde_json::from_slice(&fs::read("/home/ubuntu/src/zk-tools/zopro/docs/benchmarks/2026-10-30-g2-vector-sign-adoption176/artifacts/production-source-manifest.json").unwrap()).unwrap();let rows=s.lines().filter(|l|l.starts_with('|')&&l.ends_with("|")&&l.matches('×').count()==2).collect::<Vec<_>>();assert_eq!(rows.len(),8);for row in rows{let c=row.split('|').collect::<Vec<_>>();let name=if c[1]=="merge24"{"merge-24x1"}else{c[1]};let r=&m["m5"][name];let ms=c[2].parse::<f64>().unwrap();assert!((ms-r["accepted_ms"].as_f64().unwrap()).abs()<1e-9);assert_eq!(c[4].parse::<f64>().unwrap(),r["cpu_reference_ms"].as_f64().unwrap());assert_eq!(c[5].parse::<f64>().unwrap(),r["metal_reference_ms"].as_f64().unwrap());assert_eq!(r["goal10x"],false);}let mut rest=s.as_str();let mut links=0;while let Some(i)=rest.find("]("){rest=&rest[i+2..];let end=rest.find(')').unwrap();let path=Path::new(D).join(&rest[..end]);assert!(path.is_file(),"{}",path.display());links+=1;rest=&rest[end+1..];}assert_eq!(links,13);fs::copy(file!(),format!("{D}/artifacts/editorial.rs")).unwrap();let mut files=vec![];walk(Path::new(D),&mut files);files.sort();let mut sums=String::new();for f in files{let rel=f.strip_prefix(D).unwrap();if rel==Path::new("SHA256SUMS"){continue;}sums.push_str(&format!("{:x}  {}\n",Sha256::digest(fs::read(&f).unwrap()),rel.display()));}fs::write(format!("{D}/SHA256SUMS"),sums).unwrap();println!("Editorialonly;8acceptedCPU/Metalrows+13linksPASS;checksumsclosed");}
